import {createApp} from '../../src/app';import {prisma} from '../../src/prisma';import {redis} from '../../src/redis';
import {encryptToken,decryptToken} from '../../src/utils/tokenCrypto';import {createInvitationRepository} from '../../src/facebookPageImportInvitations/repository';import {createInvitationFlows} from '../../src/facebookPageImportInvitations/flows';import {createInvitationOAuth} from '../../src/facebookPageImportInvitations/oauth';import {createFacebookPageImportInvitationService} from '../../src/facebookPageImportInvitations/service';import {createInvitationMaintenance} from '../../src/facebookPageImportInvitations/maintenance';
const graph={authorizationUrl:(state:string)=>'https://www.facebook.com/v20.0/dialog/oauth?state='+state,discover:async(code:string)=>{if(code!=='controlled-code')throw Error('Controlled fixture rejects other codes');return{providerUserId:'900',pages:['100','101','102'].map(pageId=>({pageId,name:'Page '+pageId,avatarUrl:null,profileUrl:'https://www.facebook.com/'+pageId,pageToken:'synthetic-'+pageId,scopes:['pages_manage_posts','pages_read_engagement'],expiresAt:null})),rejected:[]};},revalidate:async(pages:any)=>pages};
const repo=createInvitationRepository({db:prisma,encrypt:encryptToken,decrypt:decryptToken,appId:'123'}),flows=createInvitationFlows(redis);
const runtime={service:createFacebookPageImportInvitationService({db:prisma,appId:'123',repo,graph,encrypt:encryptToken}),oauth:createInvitationOAuth({db:prisma,appId:'123',repo,flows,graph}),flows,maintain:createInvitationMaintenance(prisma)};
const server=createApp({pageImport:runtime}).listen(0,'127.0.0.1',()=>process.send?.({port:(server.address() as any).port}));
process.on('message',async message=>{if(message!=='stop')return;server.closeAllConnections();server.close(async()=>{await prisma.$disconnect();redis.disconnect();process.exit(0);});});
